                elif op == '-':
                    values.append(val1 - val2)
                elif op == '*':
                    values.append(val1 * val2)
            if not ops:
                raise ValueError("Mismatched parentheses")
            ops.pop()  # Remove the '('
        else:  # Operator
            while ops and ops[-1] != '(' and (
                (token in '+-' and ops[-1] in '+-*') or
                (token in '*/' and ops[-1] in '*/')
            ):
                val2 = values.pop()
                val1 = values.pop()
                op = ops.pop()
                if op == '+':
                    values.append(val1 + val2)
                elif op == '-':
                    values.append(val1 - val2)
                elif op == '*':
                    values.append(val1 * val2)
            ops.append(token)
        i += 1
    while ops:
        val2 = values.pop()
        val1 = values.pop()
        op = ops.pop()
        if op == '+':
            values.append(val1 + val2)
        elif op == '-':
            values.append(val1 - val2)
        elif op == '*':
            values.append(val1 * val2)
    if len(values) != 1:
        raise ValueError("Invalid expression")
    return values[0]

