import sys
import re
from datetime import datetime, timezone

def parse_recipe(file_path):
    with open(file_path, 'r') as file:
        lines = file.readlines()

    variables = {}
    line_number = 1
    first_error = None

    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith('#'):
            line_number += 1
            continue

        match = re.match(r'^([a-z_]+)\s*=\s*(.*)$', stripped)
        if not match:
            if first_error is None:
                print(f"{datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')} ERROR line {line_number}: invalid expression", file=sys.stderr)
                sys.exit(1)
            continue

        name, expr = match.groups()
        if not re.fullmatch(r'[a-z_]+', name):
            if first_error is None:
                print(f"{datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')} ERROR line {line_number}: invalid name", file=sys.stderr)
                sys.exit(1)
            continue

        try:
            value = eval(expr, {}, variables)
        except NameError as e:
            missing_name = e.args[0]
            if first_error is None:
                print(f"{datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')} ERROR line {line_number}: unknown name '{missing_name}'", file=sys.stderr)
                sys.exit(1)
        except Exception:
            if first_error is None:
                print(f"{datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')} ERROR line {line_number}: invalid expression", file=sys.stderr)
                sys.exit(1)

        variables[name] = value
        print(f"{name}={value}")
        print(f"{datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')} INFO computed {name}={value}", file=sys.stderr)
        line_number += 1

    return 0

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python calc_recipe.py <recipe_file>", file=sys.stderr)
        sys.exit(1)
    sys.exit(parse_recipe(sys.argv[1]))
